import { useState, KeyboardEvent } from 'react';
import { Input, Tag, Stack } from '@jinx-ui/react';

interface TagInputProps {
  onChange?: (tags: string[]) => void;
}

export default function TagInput({ onChange }: TagInputProps) {
  const [tags, setTags] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState('');

  const updateTags = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const addTag = (value: string) => {
    const trimmed = value.trim();
    if (!trimmed || tags.includes(trimmed)) return;
    updateTags([...tags, trimmed]);
  };

  const removeTag = (index: number) => {
    updateTags(tags.filter((_, i) => i !== index));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag(inputValue);
      setInputValue('');
    } else if (event.key === 'Backspace' && inputValue === '' && tags.length > 0) {
      removeTag(tags.length - 1);
    }
  };

  const handleBlur = () => {
    if (inputValue.trim()) {
      addTag(inputValue);
      setInputValue('');
    }
  };

  return (
    <Stack direction="column" gap="var(--jx-space-2)" className="jx-w-full">
      <Input
        value={inputValue}
        onChange={(e: React.ChangeEvent<HTMLInputElement>) => setInputValue(e.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={handleBlur}
        placeholder="Введите тег и нажмите Enter"
        aria-label="Добавить тег"
      />
      {tags.length > 0 && (
        <Stack direction="row" gap="var(--jx-space-1)" wrap="wrap">
          {tags.map((tag, index) => (
            <Tag
              key={tag}
              onRemove={() => removeTag(index)}
              aria-label={`Тег ${tag}`}
            >
              {tag}
            </Tag>
          ))}
        </Stack>
      )}
    </Stack>
  );
}

